bool AUnmadePrototypeHub::CommitExperience(const UnmadeCore::PlayerExperience& before,AUnmadeCharacter* p){if(bExperienceRejected||!WriteWorldSnapshot(p)){Experience=before;NotifyRpg(TEXT("Experience could not save; progress and rewards restored."));return false;}NextExperienceRefresh=0;RefreshPlayerExperience();if(p&&p->GetEquipment()){auto b=ActiveBuild();p->GetEquipment()->SetBuildBonuses(b.attack,b.armor);}return true;}
bool AUnmadePrototypeHub::IsRealmKnown(int a)const{return a>=0&&a<9&&!bExpeditionSaveRejected&&(Experience.CityKnown(a)||UnmadeCore::MapKnowsCity(*Expeditions.Arc(a)));}
bool AUnmadePrototypeHub::TrackExperienceRealm(int a,AUnmadeCharacter* p){auto old=Experience;if(bExperienceRejected||!Experience.Track(a,Expeditions))return false;return CommitExperience(old,p);}
void AUnmadePrototypeHub::LearnExperienceTutorial(int bit,AUnmadeCharacter* p){if(bExperienceRejected)return;auto old=Experience;if(Experience.Learn(bit))CommitExperience(old,p);}
bool AUnmadePrototypeHub::ExperienceServicesOpen(int a)const{return UnmadeCore::ServiceOpen(a,Clock.MinuteOfDay()/60);}
FString AUnmadePrototypeHub::ExperienceServiceHours(int a)const{return FString::Printf(TEXT("%s: %s. Current local hour %02d. The refuge bed can wait six game hours; obligations remain due."),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].interior),a==2?TEXT("continuous furnace shifts"):a==6?TEXT("open 18:00–06:00"):TEXT("open 06:00–22:00"),Clock.MinuteOfDay()/60);}
void AUnmadePrototypeHub::RefreshPlayerExperience(){if(!GetWorld()||WingGuardians.Num()!=9||GetWorld()->GetTimeSeconds()<NextExperienceRefresh)return;NextExperienceRefresh=GetWorld()->GetTimeSeconds()+.2;int town=0;auto* p=Cast<AUnmadeCharacter>(UGameplayStatics::GetPlayerCharacter(GetWorld(),0));
 for(int a=0;a<9;++a){auto* x=Experience.Arc(a);auto* d=Depth.Arc(a);bool safe=!bExperienceRejected&&!bDepthSaveRejected;if(WingExitGates[a].IsValid()){WingExitGates[a]->SetActorHiddenInGame(safe&&x->tool);WingExitGates[a]->SetActorEnableCollision(!safe||!x->tool);}if(WingRootGates[a].IsValid()){auto* rite=p?p->FindComponentByClass<UUnmadeTenfoldComponent>():nullptr;bool open=safe&&rite&&rite->RiteStage(UnmadeCore::RiteId::LivingRoads)>=2;WingRootGates[a]->SetActorHiddenInGame(open);WingRootGates[a]->SetActorEnableCollision(!open);}if(WingLift[a].IsValid()){FVector at=Station(a,2)+FVector(0,0,-100);double lift=FMath::Sin(GetWorld()->GetTimeSeconds()*.35)*45;WingLift[a]->SetActorLocation(at+FVector(0,0,lift),false);}
  if(p&&a==1&&x->offered&&!x->complete){double phase=FMath::Fmod(GetWorld()->GetTimeSeconds(),12.);if(phase>=9&&Near(p,Wing(a,1),750)){p->GetCombat()->ReceiveHazardPulse(GetUniqueID()*128ULL+a,static_cast<uint64>(GetWorld()->GetTimeSeconds()/12)+1,10);}}
  if(p&&!bExperienceRejected&&FVector::DistSquared2D(p->GetActorLocation(),City(a))<FMath::Square(2500.f)){auto old=Experience;if(Experience.DiscoverCity(a,true)&&!WriteWorldSnapshot(p))Experience=old;}
  for(int site=0;site<(a==0?5:3);++site,++town){bool room=safe&&(d->choice==1||x->privilege||x->reconciled);if(SettlementRoomGates[town].IsValid()){SettlementRoomGates[town]->SetActorHiddenInGame(room);SettlementRoomGates[town]->SetActorEnableCollision(!room);}if(SettlementRepairs[town].IsValid()){SettlementRepairs[town]->SetActorHiddenInGame(safe&&x->repair);SettlementRepairs[town]->SetActorEnableCollision(!safe||!x->repair);}if(ExperienceSigns[town].IsValid())ExperienceSigns[town]->GetTextRender()->SetText(FText::FromString(FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].interior))+TEXT("\n")+ExperienceServiceHours(a)+FString::Printf(TEXT("\n%s / %s / %s"),d->choice==1?TEXT("RESERVE BEDS OPEN"):d->choice==2?TEXT("PUBLIC HEARING OPEN"):TEXT("ACCORD PENDING"),x->repair?TEXT("WORK TABLE REPAIRED"):TEXT("REPAIR SHIFT AVAILABLE"),x->reconciled?TEXT("SHARED ACCESS RESTORED"):TEXT("MEDIATION AT WITNESS"))));}
 }
}
bool AUnmadePrototypeHub::WingGuardianInactive(int a)const{auto* x=Experience.Arc(a);return bExperienceRejected||bExpeditionSaveRejected||!x||x->steps!=7||x->guardian!=0;}
bool AUnmadePrototypeHub::WingGuardianYielded(int a)const{auto* x=Experience.Arc(a);return !bExperienceRejected&&x&&x->guardian==2;}
bool AUnmadePrototypeHub::RecordWingGuardian(AUnmadeEnemyCharacter* e,int a){if(bExperienceRejected||!e||!e->IsWingGuardian(a)||!e->GetCombat()->IsDefeated()||!WingGuardians.IsValidIndex(a)||WingGuardians[a].Get()!=e)return false;auto before=Experience;if(!Experience.Guardian(a))return Experience.Arc(a)&&Experience.Arc(a)->guardian==1;return CommitExperience(before,nullptr);}
bool AUnmadePrototypeHub::TryExperienceInteraction(AUnmadeCharacter* p,double competing){if(!p||!GetWorld())return false;int arc=-1,kind=-1,step=-1;double best=FMath::Min(310.*310.,competing+1.);auto Add=[&](int a,int k,int n,FVector at,AActor* object=nullptr){double d=FVector::DistSquared(p->GetActorLocation(),at);if(d<=best&&Near(p,at,310,object)){arc=a;kind=k;step=n;best=d;}};
 for(int a=0;a<9;++a){Add(a,0,0,Wing(a,0)+FVector(-650,-550,0));for(int n=0;n<3;++n)Add(a,1,n,Station(a,n));Add(a,2,0,Wing(a,2)+FVector(-600,600,0));if(a==3&&WingGuardians[a].IsValid())Add(a,3,0,WingGuardians[a]->GetActorLocation(),WingGuardians[a].Get());for(int site=0;site<(a==0?5:3);++site){Add(a,4,site,Specialty(a,site));Add(a,5,site,Hall(a,site)+FVector(-420,1450,0));}}
 if(arc<0)return false;if(bExperienceRejected||bDepthSaveRejected||bExpeditionSaveRejected){NotifyRpg(TEXT("Original experience record is protected; no progress or rewards changed."));return true;}auto before=Experience;auto deadlines=WingRelayDeadline;bool changed=false;const auto& spec=UnmadeCore::ExperienceSpecs[arc];FString line;
 if(kind==0){changed=Experience.OfferWing(arc,Expeditions);line=FString(UTF8_TO_TCHAR(spec.task))+TEXT("\n")+UTF8_TO_TCHAR(spec.hint);}
 if(kind==1){bool physical=Experience.Arc(arc)->offered;double now=GetWorld()->GetTimeSeconds();if(arc==0){auto* guide=Resident(GetWorld(),arc,4);physical=physical&&(Experience.Arc(arc)->scenes&1)&&guide&&FVector::DistSquared2D(guide->GetActorLocation(),Station(arc,step))<FMath::Square(450.f);}if(arc==1)physical=physical&&FMath::Fmod(now,12.)<7;if(arc==2){if(WingRelayDeadline[arc]<now&&Experience.Arc(arc)->steps)changed=Experience.RestartCooling(arc);if(step==0)WingRelayDeadline[arc]=now+20;physical=physical&&WingRelayDeadline[arc]>=now;}if(arc==3)physical=physical&&p->GetCombat()->IsGuarding();if(arc==4&&step>0)physical=physical&&p->GetActorLocation().Z>City(arc).Z+180;if(arc==5)physical=physical&&p->GetRealityStrain()<35;if(arc==6)physical=physical&&p->bIsCrouched&&Quiet(GetWorld(),p,arc);if(arc==7){auto* rite=p->FindComponentByClass<UUnmadeTenfoldComponent>();physical=physical&&rite&&rite->RiteStage(UnmadeCore::RiteId::LivingRoads)>=2;}if(arc==8&&step==2)physical=physical&&WingLift[arc].IsValid()&&p->GetMovementBase()==WingLift[arc]->GetStaticMeshComponent()&&p->GetActorLocation().Z>City(arc).Z+325;bool progressed=Experience.WingStep(arc,step,physical);changed=changed||progressed;line=progressed?TEXT("Fieldwork station registered. The guardian wakes after all three steps."):FString(UTF8_TO_TCHAR(spec.hint));}
 if(kind==2){changed=Experience.CompleteWing(arc);line=changed?TEXT("Optional adventure complete. Three insight earned; builds, tools, bindings and privileges are now available in J."):TEXT("Finish all fieldwork stations and resolve the actual wing guardian first.");}
 if(kind==3){auto* guardian=WingGuardians[arc].Get();if(guardian&&guardian->CanBeTargeted()&&p->GetCombat()->IsGuarding()&&guardian->GetCombat()->GetHealth()<=guardian->GetCombat()->GetMaxHealth()*.25)changed=Experience.Guardian(arc,true);line=changed?TEXT("The wounded duelist yields alive. Two insight earned; this encounter is remembered."):TEXT("Guard and speak when the actual duelist is wounded below one-quarter health. Defeating them is also possible.");}
 if(kind==4)return ExperienceAction(9,p),true;if(kind==5)return ExperienceAction(11,p),true;
 if(changed&&!CommitExperience(before,p)){WingRelayDeadline=deadlines;return true;}NotifyRpg(line);return true;
}
bool AUnmadePrototypeHub::ExperienceScene(int a,int scene,AUnmadeCharacter* p){auto* speaker=Resident(GetWorld(),a,scene==0?4:scene==1?3:scene==2?0:1);if(!speaker||!Near(p,speaker->GetActorLocation(),310,speaker))return false;if(a==0&&scene==0){auto action=speaker->DecideForPlayer(true);if(action==UnmadeCore::NpcAction::AvoidPlayer||action==UnmadeCore::NpcAction::RefuseTrade){NotifyRpg(speaker->GetDisplayLabel()+TEXT(" declines to guide you while afraid. Their refusal remains respected."));return false;}}auto before=Experience;if(!Experience.Scene(a,scene,Expeditions,Depth)||!CommitExperience(before,p))return false;const TCHAR* gestures[]={TEXT("Gesture"),TEXT("Speak"),TEXT("Inspect"),TEXT("Release")};double seconds=FMath::Clamp(FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].scenes[scene])).Len()/14.,7.,20.);speaker->BeginDirectedBlocking(p->GetActorLocation(),seconds,FName(gestures[scene]));RpgSceneNotice=speaker->GetDisplayLabel()+TEXT(": ")+UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].scenes[scene]);RpgSceneUntil=GetWorld()->GetTimeSeconds()+seconds;NotifyRpg(RpgSceneNotice);return true;}

bool AUnmadePrototypeHub::RecordExperienceConversation(FName id,AUnmadeCharacter* p){int a,n;if(bExperienceRejected||!PersonIndex(id,a,n)||!p)return false;auto* real=Resident(GetWorld(),a,n);if(!real||!Near(p,real->GetActorLocation(),310,real))return false;auto before=Experience;if(Experience.Visit(a,n,GetGameDay())&&!CommitExperience(before,p))return false;for(int scene=0;scene<4;++scene)if(ExperienceScene(a,scene,p))break;return true;}
FString AUnmadePrototypeHub::ExperienceReaction(FName id)const{int a,n;if(!PersonIndex(id,a,n)||bExperienceRejected)return FString();auto* x=Experience.Arc(a);auto* d=Depth.Arc(a);if(!x->visits[n]||(!d->choice&&!x->guardian&&!x->repair)||((n==1||n==2)&&!(Expeditions.Arc(a)->rescued&(1<<(n-1)))))return FString();FString line=FString::Printf(TEXT("%s remembers %d distinct days with you. "),UTF8_TO_TCHAR(UnmadeCore::ExpeditionSpecs[a].people[n]),x->visits[n]);if(d->choice)line+=UTF8_TO_TCHAR(d->choice==1?UnmadeCore::ExperienceSpecs[a].reserve_return:UnmadeCore::ExperienceSpecs[a].witness_return);if(x->guardian)line+=x->guardian==2?TEXT(" The wing guardian yielded alive. "):TEXT(" The wing guardian died. ");if(x->repair)line+=TEXT(" The repaired work table has reopened the local shift. ");if(x->reconciled)line+=TEXT(" Mediation restored shared access; the original accord remains. ");return line;}
bool AUnmadePrototypeHub::ExperienceRoutineTarget(FName id,const FVector& current,FVector& target)const{int a,n;if(bExperienceRejected||!PersonIndex(id,a,n))return false;auto* x=Experience.Arc(a);auto* d=Depth.Arc(a);if(a==0&&n==4&&x->offered&&(x->scenes&1)&&!x->complete){auto* p=Cast<AUnmadeCharacter>(UGameplayStatics::GetPlayerCharacter(GetWorld(),0));if(!p||FVector::DistSquared2D(p->GetActorLocation(),current)>FMath::Square(700.f)){target=current;return true;}int step=x->steps==0?0:x->steps==1?1:2;if(EscortTrail.IsEmpty()||FVector::DistSquared2D(EscortTrail.Last(),p->GetActorLocation())>FMath::Square(180.f)){EscortTrail.Add(p->GetActorLocation());if(EscortTrail.Num()>256)EscortTrail.RemoveAt(0);}while(EscortTrail.Num()>1&&FVector::DistSquared2D(EscortTrail[0],current)<FMath::Square(100.f))EscortTrail.RemoveAt(0);target=EscortTrail.Num()?EscortTrail[0]:Station(a,step);return true;}if(!d->choice)return false;auto Approach=[&](FVector goal,FVector hall){auto q=UnmadeCore::ServiceApproach(current.X,current.Y,goal.X,goal.Y,hall.X,hall.Y);return FVector(q.x,q.y,current.Z);};bool open=ExperienceServicesOpen(a);if(n==4){int site=open&&x->repair?0:2;target=Approach(Hall(a,site)+FVector(-350,open&&x->repair?700:900,0),Hall(a,site));return true;}if(n==3){target=d->choice==2&&!x->reconciled?Approach(Hall(a,0)+FVector(400,800,0),Hall(a,0)):City(a)+FVector(-2600,11000,0);return true;}if(open&&x->repair&&(n==1||n==2)&&Expeditions.Arc(a)->returned&&(Expeditions.Arc(a)->rescued&(1<<(n-1)))){target=Approach(Hall(a,0)+FVector(n==1?-350:350,900,0),Hall(a,0));return true;}return false;}
UnmadeCore::BuildEffect AUnmadePrototypeHub::ActiveBuild()const{int a=Experience.ActiveBuild();auto* x=Experience.Arc(a);if(bExperienceRejected||!x)return {};auto b=UnmadeCore::BuildEffects(x->build);if(x->recipe)b.armor+=2;return b;}
bool AUnmadePrototypeHub::ExperienceCheckpoint(const FVector& current,FVector& at)const{double best=1e30;bool found=false;for(int a=0;a<9;++a)if((Expeditions.Arc(a)->visited&1)||Experience.CityKnown(a)){double d=FVector::DistSquared2D(current,City(a));if(d<best){best=d;at=Hall(a,1)+FVector(0,-700,40);found=true;}}return found;}
bool AUnmadePrototypeHub::ExperienceAction(int action,AUnmadeCharacter* p){if(!p||!p->GetCombat()||p->GetCombat()->IsDefeated()||bExperienceRejected||bDepthSaveRejected||bExpeditionSaveRejected)return false;int a=-1;double best=FMath::Square(310.f);for(int r=0;r<9;++r)for(int site=0;site<(r==0?5:3);++site){FVector target=action==11?Hall(r,site)+FVector(-420,1450,0):action==9?Specialty(r,site):action==7?Hall(r,site)+FVector(420,1000,0):Hall(r,site)+FVector(0,1000,0);AActor* ignored=nullptr;if(action==8){auto* witness=Resident(GetWorld(),r,3);if(!witness)continue;target=witness->GetActorLocation();ignored=witness;}double distance=FVector::DistSquared(p->GetActorLocation(),target);if(distance<best&&Near(p,target,310,ignored)){a=r;best=distance;}}if(a<0){NotifyRpg(TEXT("Use upgrades and local services beside a real settlement workbench."));return false;}auto before=Experience;auto oldClock=Clock;bool changed=false;FString line;
 if(action>=1&&action<=6){if(!ExperienceServicesOpen(a)){NotifyRpg(ExperienceServiceHours(a));return false;}changed=Experience.Upgrade(a,action);line=changed?action<=3?TEXT("Build selected. Duelist: +5 attack, -2 armor, 20% higher stamina cost. Warden: +5 armor, -2 attack, 10% slower. Pathfinder: 10% reach, 8% speed, 10% higher cost. First build costs two insight; changing costs one."):action==4?FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].tool))+TEXT(" earned. The wing shortcut is now physically open."):action==5?FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].recipe))+TEXT(" crafted from one insight. Its fitted binding adds two armor to this active realm build."):TEXT("Local privilege earned. The shared room and two daily specialty uses are available."):TEXT("Complete this optional wing first. First build costs two insight; each tool, binding or privilege costs one. Changing build costs one.");}
 if(action==7){changed=Experience.Repair(a,Depth);line=changed?TEXT("One insight committed to the repair shift. Rubble cleared, the work table and returning residents can resume local work."):TEXT("A personal accord, completed wing and one unspent insight are required. Repairs are permanent.");}
 if(action==8){auto* witness=Resident(GetWorld(),a,3);changed=witness&&Near(p,witness->GetActorLocation(),310,witness)&&Experience.Reconcile(a,Depth);line=changed?TEXT("The witness mediated shared access. The original public accord and all remembered disagreements remain intact."):TEXT("Speak beside the real witness on a second distinct day after repairing the work table. Public-witness accord required.");}
 if(action==9){if(!ExperienceServicesOpen(a)){NotifyRpg(ExperienceServiceHours(a));return false;}bool useful=a==1?p->GetRealityStrain()>0:a==5?p->GetCombat()->HasTemporaryStatus():a==7?p->GetCombat()->GetMissingHealth()>0:true;changed=useful&&Experience.Specialty(a,GetGameDay());line=changed?FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].specialty))+TEXT(" provided. One service per game day; two total per realm, shared between settlements."):TEXT("Earn local privilege first. Specialty services have two total uses, one per game day; no use is charged when recovery cannot help.");}
 if(action==11){bool mayRest=Depth.Arc(a)->choice==1||Experience.Arc(a)->privilege||Experience.Arc(a)->reconciled;if(!mayRest){NotifyRpg(TEXT("The reserve beds require a protected accord, privilege or mediated shared access."));return false;}if(GetWorld()->GetTimeSeconds()>ExperienceWaitConfirm){ExperienceWaitConfirm=GetWorld()->GetTimeSeconds()+20;NotifyRpg(TEXT("WAIT SIX GAME HOURS: wages, debts and supplies follow world time. Press Rest again to confirm; story choices remain unchanged."));return false;}ExperienceWaitConfirm=-1;for(int i=0;i<300;++i)Clock.Advance(1);changed=true;line=TEXT("Six game hours passed. Local hours and routines changed; existing obligations remain due.");}
 if(!changed){NotifyRpg(line);return false;}if(!CommitExperience(before,p)){Clock=oldClock;return false;}
 if(action==7||action==8)p->ReportIntegrationEvent(FName(action==7?TEXT("World.LocalRepair"):TEXT("World.LocalMediation")),FName(*FString::Printf(TEXT("npc.expedition.%d.3"),a)));
 if(action==9){switch(a){case 0:TrackExperienceRealm(a,p);break;case 1:p->RecoverIntegrationStrain(20);break;case 2:p->GetCombat()->GrantPressure(GetWorld()->GetTimeSeconds());break;case 3:p->ReportIntegrationEvent(FName(TEXT("World.LocalMediation")),FName(*FString::Printf(TEXT("npc.expedition.%d.3"),a)));break;case 4:p->GetCombat()->GrantEvasion(GetWorld()->GetTimeSeconds(),1);break;case 5:p->GetCombat()->ClearTemporaryStatus();break;case 6:p->GetCombat()->GrantQuiet(GetWorld()->GetTimeSeconds());break;case 7:p->GetCombat()->Heal(25);break;case 8:p->GetCombat()->GrantWard(GetWorld()->GetTimeSeconds());break;}}
 NotifyRpg(line);return true;
}
FString AUnmadePrototypeHub::GetTrackedObjective()const{
 int a=Experience.Tracked();if(!IsRealmKnown(a))return TEXT("Explore a settlement and read its adventure board. J tracks discoveries.");
 auto goal=UnmadeCore::NextRealmObjective(*Expeditions.Arc(a),*Depth.Arc(a),*Experience.Arc(a));const auto& spec=UnmadeCore::ExpeditionSpecs[a];using S=UnmadeCore::JourneyStep;FString task;
 switch(goal.step){
 case S::Board:task=TEXT("Read the city's adventure board to hear the local problem");break;
 case S::Frontier:task=FString::Printf(TEXT("Visit %s north of the city; inspect its local witness marker"),UTF8_TO_TCHAR(spec.frontier));break;
 case S::Chamber:task=FString::Printf(TEXT("Enter chamber %d; arrival records the room before combat"),goal.index+1);break;
 case S::Resolution:task=TEXT("At the holding-chamber council: E chooses rescued captives; F chooses all three evidence records");break;
 case S::Boss:task=TEXT("Resolve the arena boss; the evidence branch also permits a living surrender");break;
 case S::Return:task=FString::Printf(TEXT("Follow the opened return walk to %s's equipment bench; the leader must witness your return"),UTF8_TO_TCHAR(spec.frontier));break;
 case S::Reward:task=TEXT("Choose the earned weapon with E or armor with F at the frontier bench; preview in Equipment");break;
 case S::PersonalOffer:task=FString::Printf(TEXT("Speak beside %s for the personal quest offer"),UTF8_TO_TCHAR(spec.people[0]));break;
 case S::Witness:task=FString::Printf(TEXT("Find %s at the refuge or hearing room and listen to the personal account"),UTF8_TO_TCHAR(spec.people[3]));break;
 case S::PersonalEvidence:task=TEXT("Inspect the personal evidence in chamber four after hearing the witness");break;
 case S::Accord:task=TEXT("Return to the leader; review and confirm protected reserve or public witness");break;
 case S::WingOffer:task=TEXT("The optional fieldwork wing branches east from the farthest-east chamber; discover that chamber first");break;
 case S::WingFieldwork:task=FString::Printf(TEXT("%s: complete station %d; %s"),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].task),goal.index+1,UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].hint));break;
 case S::WingGuardian:task=FString::Printf(TEXT("Resolve %s at the final wing room"),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].guardian));break;
 case S::WingReward:task=TEXT("Claim insight at the final wing reward station; defeating its guardian alone does not claim it");break;
 case S::Home:task=TEXT("Adventure resolved. Optional: meet returning people, buy upgrades, repair the work table, and mediate shared access");break;
 }
 return FString(UTF8_TO_TCHAR(spec.city))+TEXT(" — ")+task;
}
FString AUnmadePrototypeHub::GetExperienceJournal()const{FString t=TEXT("TRACKED OBJECTIVE\n")+GetTrackedObjective()+TEXT("\n\nOPTIONAL FIELDWORK AND RETURN RELATIONSHIPS\n");for(int a=0;a<9;++a){auto* x=Experience.Arc(a);if(!x->offered)continue;int completed=0;for(int n=0;n<3;++n)completed+=(x->steps&(1<<n))?1:0;const TCHAR* builds[]={TEXT("none"),TEXT("Duelist"),TEXT("Warden"),TEXT("Pathfinder")};t+=FString::Printf(TEXT("%s / %s: fieldwork %d/3; guardian %s; completion %s.\nInsight %d; build %s; tool %s; binding %s; privilege %s; repairs %s; mediation %s.\n%s\n"),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].city),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].task),completed,x->guardian==2?TEXT("yielded alive"):x->guardian?TEXT("defeated"):TEXT("unresolved"),x->complete?TEXT("claimed"):TEXT("pending"),x->insight,builds[x->build],x->tool?TEXT("earned"):TEXT("pending"),x->recipe?TEXT("crafted"):TEXT("pending"),x->privilege?TEXT("earned"):TEXT("pending"),x->repair?TEXT("complete"):TEXT("pending"),x->reconciled?TEXT("shared access restored"):TEXT("pending"),UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].hint));}t+=TEXT("\nUPGRADE COSTS: first build 2 insight; a different build 1; tool 1; crafted binding 1 (+2 armor); privilege 1; repair 1. Wing gives 5 total insight; four earned relationship scenes can add 4. Spending is finite.\n");if(!GetDefault<UUnmadePlayerPreferences>()->ShowTutorials)return t;int tutorial=Experience.Tutorial();if(!(tutorial&1))t+=TEXT("FIRST STEPS: use E beside a real person or object. F inspects alternate evidence. J opens your journal.\n");if(!(tutorial&2))t+=TEXT("EXPLORATION: walk inside rooms or inspect their entrances to record visits. Undiscovered rooms remain hidden on the map.\n");if(!(tutorial&4))t+=TEXT("COMBAT: left mouse attacks; contact follows windup. Right mouse guards; time guard entry to parry. Shift dodges. Watch enemy warnings.\n");if(!(tutorial&8))t+=TEXT("EQUIPMENT: selecting a weapon or armor replaces that slot. Techniques and charm modifiers remain distinct.\n");if(!(tutorial&16))t+=TEXT("CONSEQUENCES: personal decisions need confirmation. Public witness attracts a road claimant; repairs and mediation can restore access.\n");return t;}
FString AUnmadePrototypeHub::GetExperienceMap(int a,AUnmadeCharacter* p)const{if(!IsRealmKnown(a))return TEXT("Unrecorded realm. Find an adventure board or arrive through an earned route before its local map is revealed.");const auto& s=UnmadeCore::ExpeditionSpecs[a];auto* e=Expeditions.Arc(a);auto* d=Depth.Arc(a);auto* x=Experience.Arc(a);FString t=FString(UTF8_TO_TCHAR(s.city))+TEXT("\n");if(p){FVector delta=City(a)-p->GetActorLocation();t+=FString::Printf(TEXT("City bearing: %.0f m east, %.0f m north; %.0f m away.\n"),delta.X/100,delta.Y/100,delta.Size2D()/100);}t+=TEXT("Recorded frontier: ")+FString(e->visited&1?UTF8_TO_TCHAR(s.frontier):TEXT("not visited"))+TEXT(" / refuge: ")+FString(e->visited&2?UTF8_TO_TCHAR(s.refuge):TEXT("not visited"))+TEXT("\n");for(int room=0;room<6;++room){if(!UnmadeCore::MapKnowsRoom(*e,room)){t+=FString::Printf(TEXT("Chamber %d: undiscovered\n"),room+1);continue;}auto c=UnmadeCore::DungeonRoom(a,room);t+=FString::Printf(TEXT("Recorded chamber %d: %.0f m east, %.0f m north of city\n"),room+1,c.x/100.,(15000+c.y)/100.);}if(x->offered){t+=FString(UTF8_TO_TCHAR(UnmadeCore::ExperienceSpecs[a].wing))+TEXT("\n");for(int n=0;n<3;++n)if(x->steps&(1<<n)){auto c=UnmadeCore::WingRoom(a,n);t+=FString::Printf(TEXT("Recorded wing station %d: %.0f m east, %.0f m north\n"),n+1,c.x/100.,(15000+c.y)/100.);}}if(UnmadeCore::MapKnowsChoice(*d))t+=TEXT("Known personal options:\nA: ")+FString(UTF8_TO_TCHAR(UnmadeCore::DepthSpecs[a].option_a))+TEXT("\nB: ")+FString(UTF8_TO_TCHAR(UnmadeCore::DepthSpecs[a].option_b));else t+=TEXT("Personal options are unknown until the offer and witness conversation.");if(a==0)t+=TEXT("\nThe Reach also includes Bellwold and Paperhaven.");return t;}

bool AUnmadePrototypeHub::SelectExperienceBuild(int a,AUnmadeCharacter* p){if(!p||bExperienceRejected)return false;auto old=Experience;if(!Experience.SelectBuild(a)){NotifyRpg(TEXT("Earn a build or binding in this realm first, or select a different owned build."));return false;}if(!CommitExperience(old,p))return false;NotifyRpg(TEXT("Owned realm build selected without spending insight. Equipment and active technique remain independently selected."));return true;}

bool AUnmadePrototypeHub::RecordWingObserver(AUnmadeEnemyCharacter* e){if(bExperienceRejected||WingObserver.Get()!=e||!e||!e->IsWingObserver()||!e->GetCombat()->IsDefeated())return false;auto old=Experience;if(!Experience.ClearObserver(6))return Experience.ObserverCleared();return CommitExperience(old,nullptr);}

bool AUnmadePrototypeHub::TryFieldCraft(AUnmadeCharacter* p,int a){if(a<0||a>=9||!p||!p->GetEquipment()||!KnowsFieldRecipe(a)||!ExperienceServicesOpen(a)||bExperienceRejected){NotifyRpg(TEXT("Earn this field recipe in its wing, then use the local workbench during open hours."));return false;}bool local=false;for(int site=0;site<(a==0?5:3);++site)local=local||Near(p,Hall(a,site)+FVector(0,1000,0));if(!local){NotifyRpg(TEXT("Approach this realm’s physical workbench to craft its recipe."));return false;}bool made=p->GetEquipment()->CraftFieldRecipe(a,true);NotifyRpg(made?TEXT("Selected field recipe crafted and saved. Ingredients spent; original wages and local insight are unchanged."):TEXT("Craft not completed: check ingredients, output capacity and save availability."));return made;}

FName AUnmadePrototypeHub::ServiceWorkCue(FName person,const FVector& at)const{int a,n;if(!PersonIndex(person,a,n)||bExperienceRejected||!Experience.Arc(a)->repair||!ExperienceServicesOpen(a)||FVector::DistSquared2D(at,Hall(a,0)+FVector(0,1000,0))>FMath::Square(650.f)||!GetWorld()||FMath::Fmod(GetWorld()->GetTimeSeconds()+a*2+n,16.0)>5)return NAME_None;int cue=UnmadeCore::WorkMotion(a,n);return FName(cue==0?TEXT("Repair"):cue==1?TEXT("Inspect"):TEXT("Gesture"));}
